WITH months AS (SELECT DISTINCT CAST(date_trunc('month', date_day) AS DATE) AS month_start, CAST(date_trunc('month', date_day) + INTERVAL '1 month' - INTERVAL '1 day' AS DATE) AS month_end FROM {{ ref('time_spine') }}), included_cards AS (SELECT card_id, member_id, card_type, valid_from, valid_until, ended_at FROM {{ ref('cards') }} WHERE card_type IN ('悦享年卡', '家庭季卡')), normal_cards AS (SELECT card_id, member_id, card_type, valid_from, valid_until, ended_at FROM included_cards WHERE valid_from IS NOT NULL AND valid_until IS NOT NULL AND valid_from < valid_until AND (ended_at IS NULL OR (ended_at > valid_from AND ended_at < valid_until))), member_months AS (SELECT mo.month_start, mo.month_end, m.member_id FROM months mo CROSS JOIN {{ ref('members') }} m), eligibility AS (SELECT mm.month_start, mm.month_end, mm.member_id, CASE WHEN EXISTS (SELECT 1 FROM normal_cards c WHERE c.member_id = mm.member_id AND c.valid_from <= mm.month_end AND mm.month_end < c.valid_until AND (c.ended_at IS NULL OR mm.month_end < c.ended_at)) THEN 'eligible' WHEN EXISTS (SELECT 1 FROM included_cards c WHERE c.member_id = mm.member_id AND (c.valid_from IS NULL OR c.valid_until IS NULL OR c.valid_from >= c.valid_until OR (c.ended_at IS NOT NULL AND NOT (c.ended_at > c.valid_from AND c.ended_at < c.valid_until)))) THEN 'pending_review' ELSE 'not_eligible' END AS eligibility_status FROM member_months mm), valid_orders AS (SELECT member_id, CAST(date_trunc('month', ordered_at) AS DATE) AS month_start, paid_cents - refund_cents AS net_sales_cents FROM {{ ref('orders') }} WHERE status = 'paid' AND paid_cents - refund_cents > 0), monthly_orders AS (SELECT member_id, month_start, COUNT(*) AS valid_order_count, SUM(net_sales_cents) AS net_sales_cents FROM valid_orders GROUP BY member_id, month_start) SELECT e.month_start, e.month_end, e.member_id, e.eligibility_status, COALESCE(mo.valid_order_count, 0) AS valid_order_count, COALESCE(mo.net_sales_cents, 0) AS net_sales_cents, e.member_id || '|' || CAST(e.month_start AS VARCHAR) AS paid_month_member_key FROM eligibility e LEFT JOIN monthly_orders mo ON e.member_id = mo.member_id AND e.month_start = mo.month_start